CREATE TABLE attribute_values (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "attribute_id"  bigint NOT NULL,
    "value_code"    varchar(255) NOT NULL,
    "label"         varchar(255),
    "sort_position" integer NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT attribute_values_uq UNIQUE (attribute_id, value_code),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (attribute_id) REFERENCES attributes (id)
);

CREATE TABLE variant_attribute_values (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "variant_id"         bigint NOT NULL,
    "attribute_id"       bigint NOT NULL,
    "attribute_value_id" bigint,
    "value_text"         varchar(4000),
    "created_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT variant_attribute_values_uq UNIQUE (variant_id, attribute_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (attribute_id) REFERENCES attributes (id),
    FOREIGN KEY (attribute_value_id) REFERENCES attribute_values (id)
);

CREATE TABLE product_media (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "product_id"    bigint NOT NULL,
    "variant_id"    bigint,
    "kind"          varchar(32) NOT NULL,
    "url"           varchar(2048) NOT NULL,
    "alt_text"      varchar(4000),
    "sort_position" integer NOT NULL,
    "is_primary"    boolean NOT NULL,
    "width_px"      integer,
    "height_px"     integer,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (width_px IS NULL OR width_px > 0),
    CHECK (height_px IS NULL OR height_px > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (product_id) REFERENCES products (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (kind) REFERENCES media_kinds (code)
);

CREATE TABLE collections (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "name"         varchar(255) NOT NULL,
    "slug"         varchar(255) NOT NULL,
    "description"  varchar(4000),
    "is_automated" boolean NOT NULL,
    "rules"        json,
    "starts_at"    timestamp,
    "ends_at"      timestamp,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    "deleted_at"   timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT collections_tenant_slug_uq UNIQUE (tenant_id, slug),
    CONSTRAINT collections_window_ck CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE collection_products (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "collection_id" bigint NOT NULL,
    "product_id"    bigint NOT NULL,
    "sort_position" integer NOT NULL,
    "created_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT collection_products_uq UNIQUE (collection_id, product_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (collection_id) REFERENCES collections (id),
    FOREIGN KEY (product_id) REFERENCES products (id)
);

CREATE TABLE tags (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "name"       varchar(255) NOT NULL,
    "slug"       varchar(255) NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT tags_tenant_slug_uq UNIQUE (tenant_id, slug),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE product_tags (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "product_id" bigint NOT NULL,
    "tag_id"     bigint NOT NULL,
    "created_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT product_tags_uq UNIQUE (product_id, tag_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (product_id) REFERENCES products (id),
    FOREIGN KEY (tag_id) REFERENCES tags (id)
);

CREATE TABLE product_reviews (
    "id"                   bigint NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "product_id"           bigint NOT NULL,
    "user_id"              bigint,
    "rating"               integer NOT NULL,
    "title"                varchar(255),
    "body"                 varchar(65535),
    "is_verified_purchase" boolean NOT NULL,
    "is_approved"          boolean NOT NULL,
    "helpful_count"        integer NOT NULL,
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT product_reviews_one_per_user_uq UNIQUE (product_id, user_id),
    CHECK (rating BETWEEN 1 AND 5),
    CHECK (helpful_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (product_id) REFERENCES products (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE review_votes (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "review_id"  bigint NOT NULL,
    "user_id"    bigint NOT NULL,
    "is_helpful" boolean NOT NULL,
    "created_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT review_votes_one_per_user_uq UNIQUE (review_id, user_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (review_id) REFERENCES product_reviews (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE product_relations (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "product_id"         bigint NOT NULL,
    "related_product_id" bigint NOT NULL,
    "relation_kind"      varchar(64) NOT NULL,
    "sort_position"      integer NOT NULL,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT product_relations_uq UNIQUE (product_id, related_product_id, relation_kind),
    CONSTRAINT product_relations_not_self_ck CHECK (product_id <> related_product_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (product_id) REFERENCES products (id),
    FOREIGN KEY (related_product_id) REFERENCES products (id)
);

CREATE TABLE product_bundles (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "product_id"  bigint,
    "name"        varchar(255) NOT NULL,
    "slug"        varchar(255) NOT NULL,
    "description" varchar(4000),
    "is_active"   boolean NOT NULL,
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT product_bundles_tenant_slug_uq UNIQUE (tenant_id, slug),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (product_id) REFERENCES products (id)
);

CREATE TABLE bundle_items (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "bundle_id"     bigint NOT NULL,
    "variant_id"    bigint NOT NULL,
    "quantity"      integer NOT NULL,
    "sort_position" integer NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT bundle_items_uq UNIQUE (bundle_id, variant_id),
    CHECK (quantity > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (bundle_id) REFERENCES product_bundles (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id)
);

-- ==========================================================================
-- pricing
-- ==========================================================================

CREATE TABLE discount_kinds (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE coupon_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE price_lists (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "name"          varchar(255) NOT NULL,
    "code"          varchar(64) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "is_default"    boolean NOT NULL,
    "is_active"     boolean NOT NULL,
    "starts_at"     timestamp,
    "ends_at"       timestamp,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    "deleted_at"    timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT price_lists_tenant_code_uq UNIQUE (tenant_id, code),
    CONSTRAINT price_lists_window_ck CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE prices (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "price_list_id"     bigint NOT NULL,
    "variant_id"        bigint NOT NULL,
    "currency_code"     varchar(3) NOT NULL,
    "amount"            decimal(14,4) NOT NULL,
    "compare_at_amount" decimal(14,4),
    "min_quantity"      integer NOT NULL,
    "valid_from"        timestamp NOT NULL,
    "valid_to"          timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (amount >= 0),
    CHECK (compare_at_amount IS NULL OR compare_at_amount >= 0),
    CHECK (min_quantity > 0),
    CONSTRAINT prices_window_ck CHECK (valid_to IS NULL OR valid_to > valid_from),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (price_list_id) REFERENCES price_lists (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE discounts (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "name"                varchar(255) NOT NULL,
    "kind"                varchar(32) NOT NULL,
    "discount_value"      decimal(14,4) NOT NULL,
    "currency_code"       varchar(3),
    "max_amount"          decimal(14,4),
    "min_subtotal"        decimal(14,4),
    "applies_to_shipping" boolean NOT NULL,
    "is_active"           boolean NOT NULL,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    "deleted_at"          timestamp,
    PRIMARY KEY ("id"),
    CHECK (discount_value >= 0),
    CHECK (max_amount IS NULL OR max_amount >= 0),
    CHECK (min_subtotal IS NULL OR min_subtotal >= 0),
    CONSTRAINT discounts_fixed_currency_ck CHECK (kind <> 'fixed_amount' OR currency_code IS NOT NULL),
    CONSTRAINT discounts_pct_range_ck CHECK (kind <> 'percentage' OR discount_value <= 100),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (kind) REFERENCES discount_kinds (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE coupons (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "discount_id"        bigint NOT NULL,
    "code"               varchar(64) NOT NULL,
    "status"             varchar(32) NOT NULL,
    "usage_limit"        integer,
    "per_customer_limit" integer,
    "times_redeemed"     integer NOT NULL,
    "starts_at"          timestamp,
    "expires_at"         timestamp,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    "deleted_at"         timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT coupons_tenant_code_uq UNIQUE (tenant_id, code),
    CHECK (usage_limit IS NULL OR usage_limit > 0),
    CHECK (per_customer_limit IS NULL OR per_customer_limit > 0),
    CHECK (times_redeemed >= 0),
    CONSTRAINT coupons_window_ck CHECK (expires_at IS NULL OR starts_at IS NULL OR expires_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (discount_id) REFERENCES discounts (id),
    FOREIGN KEY (status) REFERENCES coupon_statuses (code)
);

CREATE TABLE tax_categories (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "name"        varchar(255) NOT NULL,
    "code"        varchar(64) NOT NULL,
    "description" varchar(4000),
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT tax_categories_tenant_code_uq UNIQUE (tenant_id, code),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE tax_zones (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "name"           varchar(255) NOT NULL,
    "country_id"     bigint,
    "region_id"      bigint,
    "postal_zone_id" bigint,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (country_id) REFERENCES countries (id),
    FOREIGN KEY (region_id) REFERENCES regions (id),
    FOREIGN KEY (postal_zone_id) REFERENCES postal_zones (id)
);

CREATE TABLE tax_rates (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "tax_category_id" bigint NOT NULL,
    "tax_zone_id"     bigint NOT NULL,
    "name"            varchar(255) NOT NULL,
    "rate"            decimal(8,5) NOT NULL,
    "is_compound"     boolean NOT NULL,
    "is_inclusive"    boolean NOT NULL,
    "valid_from"      timestamp NOT NULL,
    "valid_to"        timestamp,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (rate >= 0 AND rate <= 1),
    CONSTRAINT tax_rates_window_ck CHECK (valid_to IS NULL OR valid_to > valid_from),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (tax_category_id) REFERENCES tax_categories (id),
    FOREIGN KEY (tax_zone_id) REFERENCES tax_zones (id)
);

CREATE TABLE price_rules (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "discount_id" bigint,
    "name"        varchar(255) NOT NULL,
    "priority"    integer NOT NULL,
    "is_active"   boolean NOT NULL,
    "stackable"   boolean NOT NULL,
    "starts_at"   timestamp,
    "ends_at"     timestamp,
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT price_rules_window_ck CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (discount_id) REFERENCES discounts (id)
);

CREATE TABLE price_rule_conditions (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "price_rule_id"   bigint NOT NULL,
    "attribute"       varchar(255) NOT NULL,
    "operator"        varchar(64) NOT NULL,
    "condition_value" json NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (price_rule_id) REFERENCES price_rules (id)
);

CREATE TABLE promotions (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "discount_id"   bigint,
    "coupon_id"     bigint,
    "name"          varchar(255) NOT NULL,
    "slug"          varchar(255) NOT NULL,
    "campaign_code" varchar(64),
    "is_active"     boolean NOT NULL,
    "starts_at"     timestamp,
    "ends_at"       timestamp,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    "deleted_at"    timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT promotions_tenant_slug_uq UNIQUE (tenant_id, slug),
    CONSTRAINT promotions_window_ck CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (discount_id) REFERENCES discounts (id),
    FOREIGN KEY (coupon_id) REFERENCES coupons (id)
);

CREATE TABLE promotion_products (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "promotion_id" bigint NOT NULL,
    "product_id"   bigint NOT NULL,
    "created_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT promotion_products_uq UNIQUE (promotion_id, product_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (promotion_id) REFERENCES promotions (id),
    FOREIGN KEY (product_id) REFERENCES products (id)
);

-- ==========================================================================
-- inventory
-- ==========================================================================

CREATE TABLE movement_kinds (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE po_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE warehouses (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "address_id" bigint,
    "code"       varchar(64) NOT NULL,
    "name"       varchar(255) NOT NULL,
    "is_default" boolean NOT NULL,
    "is_active"  boolean NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    "deleted_at" timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT warehouses_tenant_code_uq UNIQUE (tenant_id, code),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (address_id) REFERENCES addresses (id)
);

CREATE TABLE stock_locations (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "code"         varchar(64) NOT NULL,
    "name"         varchar(255),
    "kind"         varchar(64) NOT NULL,
    "is_pickable"  boolean NOT NULL,
    "is_active"    boolean NOT NULL,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT stock_locations_wh_code_uq UNIQUE (warehouse_id, code),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses (id)
);

CREATE TABLE suppliers (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "code"           varchar(64) NOT NULL,
    "name"           varchar(255) NOT NULL,
    "contact_email"  varchar(254),
    "contact_phone"  varchar(32),
    "lead_time_days" integer,
    "is_active"      boolean NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    "deleted_at"     timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT suppliers_tenant_code_uq UNIQUE (tenant_id, code),
    CHECK (lead_time_days >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE supplier_products (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "supplier_id"    bigint NOT NULL,
    "variant_id"     bigint NOT NULL,
    "supplier_sku"   varchar(64),
    "unit_cost"      decimal(14,4),
    "currency_code"  varchar(3),
    "min_order_qty"  integer,
    "lead_time_days" integer,
    "is_preferred"   boolean NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT supplier_products_uq UNIQUE (supplier_id, variant_id),
    CHECK (unit_cost >= 0),
    CHECK (min_order_qty > 0),
    CHECK (lead_time_days >= 0),
    CONSTRAINT supplier_products_cost_currency_ck CHECK ((unit_cost IS NULL) = (currency_code IS NULL)),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (supplier_id) REFERENCES suppliers (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE stock_items (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "variant_id"        bigint NOT NULL,
    "stock_location_id" bigint NOT NULL,
    "quantity"          integer NOT NULL,
    "reserved_quantity" integer NOT NULL,
    "reorder_point"     integer,
    "reorder_quantity"  integer,
    "last_counted_at"   timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT stock_items_variant_location_uq UNIQUE (variant_id, stock_location_id),
    CHECK (quantity >= 0),
    CHECK (reserved_quantity >= 0),
    CHECK (reorder_point >= 0),
    CHECK (reorder_quantity > 0),
    CONSTRAINT stock_items_reserved_le_qty_ck CHECK (reserved_quantity <= quantity),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (stock_location_id) REFERENCES stock_locations (id)
);

CREATE TABLE purchase_orders (
    "id"                 bigint NOT NULL,
    "public_id"          uuid NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "supplier_id"        bigint NOT NULL,
    "warehouse_id"       bigint,
    "po_number"          varchar(64) NOT NULL,
    "status"             varchar(32) NOT NULL,
    "currency_code"      varchar(3) NOT NULL,
    "expected_total"     decimal(14,4) NOT NULL,
    "notes"              varchar(4000),
    "ordered_at"         timestamp,
    "expected_at"        timestamp,
    "received_at"        timestamp,
    "created_by_user_id" bigint,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT purchase_orders_public_id_key UNIQUE (public_id),
    CONSTRAINT purchase_orders_tenant_number_uq UNIQUE (tenant_id, po_number),
    CHECK (expected_total >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (supplier_id) REFERENCES suppliers (id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses (id),
    FOREIGN KEY (status) REFERENCES po_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    FOREIGN KEY (created_by_user_id) REFERENCES users (id)
);

CREATE TABLE purchase_order_lines (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "purchase_order_id" bigint NOT NULL,
    "variant_id"        bigint NOT NULL,
    "quantity_ordered"  integer NOT NULL,
    "quantity_received" integer NOT NULL,
    "unit_cost"         decimal(14,4) NOT NULL,
    "currency_code"     varchar(3) NOT NULL,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT po_lines_uq UNIQUE (purchase_order_id, variant_id),
    CHECK (quantity_ordered > 0),
    CHECK (quantity_received >= 0),
    CHECK (unit_cost >= 0),
    CONSTRAINT po_lines_received_le_ordered_ck CHECK (quantity_received <= quantity_ordered),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE lots (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "variant_id"      bigint NOT NULL,
    "supplier_id"     bigint,
    "lot_code"        varchar(64) NOT NULL,
    "manufactured_at" date,
    "expires_at"      date,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT lots_tenant_variant_code_uq UNIQUE (tenant_id, variant_id, lot_code),
    CONSTRAINT lots_expiry_after_mfg_ck CHECK (expires_at IS NULL OR manufactured_at IS NULL OR expires_at >= manufactured_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (supplier_id) REFERENCES suppliers (id)
);

CREATE TABLE stock_movements (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "variant_id"         bigint NOT NULL,
    "stock_location_id"  bigint NOT NULL,
    "lot_id"             bigint,
    "kind"               varchar(32) NOT NULL,
    "quantity"           integer NOT NULL,
    "reference_type"     varchar(64),
    "reference_id"       bigint,
    "note"               varchar(4000),
    "created_by_user_id" bigint,
    "occurred_at"        timestamp NOT NULL,
    "created_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity <> 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (stock_location_id) REFERENCES stock_locations (id),
    FOREIGN KEY (kind) REFERENCES movement_kinds (code),
    FOREIGN KEY (created_by_user_id) REFERENCES users (id),
    CONSTRAINT stock_movements_lot_id_fkey FOREIGN KEY (lot_id) REFERENCES lots (id)
);

CREATE TABLE serial_numbers (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "variant_id"        bigint NOT NULL,
    "lot_id"            bigint,
    "stock_location_id" bigint,
    "serial"            varchar(64) NOT NULL,
    "status"            varchar(64) NOT NULL,
    "received_at"       timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT serial_numbers_tenant_serial_uq UNIQUE (tenant_id, serial),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (lot_id) REFERENCES lots (id),
    FOREIGN KEY (stock_location_id) REFERENCES stock_locations (id)
);

CREATE TABLE inbound_receipts (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "purchase_order_id"   bigint,
    "warehouse_id"        bigint NOT NULL,
    "receipt_number"      varchar(64) NOT NULL,
    "carrier"             varchar(64),
    "tracking_number"     varchar(64),
    "received_by_user_id" bigint,
    "received_at"         timestamp NOT NULL,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT inbound_receipts_tenant_number_uq UNIQUE (tenant_id, receipt_number),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders (id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses (id),
    FOREIGN KEY (received_by_user_id) REFERENCES users (id)
);

CREATE TABLE receipt_lines (
    "id"                     bigint NOT NULL,
    "tenant_id"              bigint NOT NULL,
    "inbound_receipt_id"     bigint NOT NULL,
    "purchase_order_line_id" bigint,
    "variant_id"             bigint NOT NULL,
    "stock_location_id"      bigint,
    "lot_id"                 bigint,
    "quantity_received"      integer NOT NULL,
    "quantity_rejected"      integer NOT NULL,
    "created_at"             timestamp NOT NULL,
    "updated_at"             timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity_received > 0),
    CHECK (quantity_rejected >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (inbound_receipt_id) REFERENCES inbound_receipts (id),
    FOREIGN KEY (purchase_order_line_id) REFERENCES purchase_order_lines (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (stock_location_id) REFERENCES stock_locations (id),
    FOREIGN KEY (lot_id) REFERENCES lots (id)
);

CREATE TABLE stock_adjustments (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "variant_id"          bigint NOT NULL,
    "stock_location_id"   bigint NOT NULL,
    "lot_id"              bigint,
    "quantity_delta"      integer NOT NULL,
    "reason"              varchar(4000) NOT NULL,
    "note"                varchar(4000),
    "adjusted_by_user_id" bigint,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity_delta <> 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (stock_location_id) REFERENCES stock_locations (id),
    FOREIGN KEY (lot_id) REFERENCES lots (id),
    FOREIGN KEY (adjusted_by_user_id) REFERENCES users (id)
);

-- ==========================================================================
-- sales
-- ==========================================================================

CREATE TABLE cart_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE order_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE fulfillment_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE return_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE carts (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "user_id"       bigint,
    "session_token" varchar(255),
    "status"        varchar(32) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "item_count"    integer NOT NULL,
    "subtotal"      decimal(14,4) NOT NULL,
    "abandoned_at"  timestamp,
    "converted_at"  timestamp,
    "expires_at"    timestamp,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (item_count >= 0),
    CHECK (subtotal >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (status) REFERENCES cart_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE cart_items (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "cart_id"            bigint NOT NULL,
    "product_variant_id" bigint NOT NULL,
    "quantity"           integer NOT NULL,
    "unit_price"         decimal(14,4) NOT NULL,
    "currency_code"      varchar(3) NOT NULL,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT cart_items_cart_variant_uq UNIQUE (cart_id, product_variant_id),
    CHECK (quantity > 0),
    CHECK (unit_price >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (cart_id) REFERENCES carts (id),
    FOREIGN KEY (product_variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE orders (
    "id"                  bigint NOT NULL,
    "public_id"           uuid NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "user_id"             bigint NOT NULL,
    "cart_id"             bigint,
    "order_number"        varchar(64) NOT NULL,
    "status"              varchar(32) NOT NULL,
    "billing_address_id"  bigint,
    "shipping_address_id" bigint,
    "currency_code"       varchar(3) NOT NULL,
    "subtotal"            decimal(14,4) NOT NULL,
    "discount_total"      decimal(14,4) NOT NULL,
    "tax_total"           decimal(14,4) NOT NULL,
    "shipping_total"      decimal(14,4) NOT NULL,
    "grand_total"         decimal(14,4) NOT NULL,
    "customer_email"      varchar(254),
    "customer_note"       varchar(4000),
    "placed_at"           timestamp,
    "cancelled_at"        timestamp,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT orders_public_id_key UNIQUE (public_id),
    CONSTRAINT orders_tenant_number_uq UNIQUE (tenant_id, order_number),
    CHECK (subtotal >= 0),
    CHECK (discount_total >= 0),
    CHECK (tax_total >= 0),
    CHECK (shipping_total >= 0),
    CHECK (grand_total >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (cart_id) REFERENCES carts (id),
    FOREIGN KEY (status) REFERENCES order_statuses (code),
    FOREIGN KEY (billing_address_id) REFERENCES addresses (id),
    FOREIGN KEY (shipping_address_id) REFERENCES addresses (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

-- ==========================================================================
-- pricing
-- ==========================================================================

CREATE TABLE coupon_redemptions (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "coupon_id"       bigint NOT NULL,
    "user_id"         bigint,
    "order_id"        bigint,
    "discount_amount" decimal(14,4) NOT NULL,
    "currency_code"   varchar(3) NOT NULL,
    "redeemed_at"     timestamp NOT NULL,
    "created_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (discount_amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (coupon_id) REFERENCES coupons (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    CONSTRAINT coupon_redemptions_order_fk FOREIGN KEY (order_id) REFERENCES orders (id)
);

-- ==========================================================================
-- inventory
-- ==========================================================================

CREATE TABLE stock_reservations (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "variant_id"        bigint NOT NULL,
    "stock_location_id" bigint NOT NULL,
    "order_id"          bigint,
    "quantity"          integer NOT NULL,
    "expires_at"        timestamp,
    "released_at"       timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (stock_location_id) REFERENCES stock_locations (id),
    CONSTRAINT stock_reservations_order_fk FOREIGN KEY (order_id) REFERENCES orders (id)
);

-- ==========================================================================
-- sales
-- ==========================================================================

CREATE TABLE order_items (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "order_id"           bigint NOT NULL,
    "product_variant_id" bigint NOT NULL,
    "sku"                varchar(64) NOT NULL,
    "name"               varchar(255) NOT NULL,
    "quantity"           integer NOT NULL,
    "quantity_fulfilled" integer NOT NULL,
    "unit_price"         decimal(14,4) NOT NULL,
    "discount_total"     decimal(14,4) NOT NULL,
    "tax_total"          decimal(14,4) NOT NULL,
    "line_total"         decimal(14,4) NOT NULL,
    "currency_code"      varchar(3) NOT NULL,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity > 0),
    CHECK (quantity_fulfilled >= 0),
    CHECK (unit_price >= 0),
    CHECK (discount_total >= 0),
    CHECK (tax_total >= 0),
    CHECK (line_total >= 0),
    CONSTRAINT order_items_fulfilled_le_qty CHECK (quantity_fulfilled <= quantity),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (product_variant_id) REFERENCES product_variants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE order_status_history (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "order_id"           bigint NOT NULL,
    "from_status"        varchar(32),
    "to_status"          varchar(32) NOT NULL,
    "changed_by_user_id" bigint,
    "note"               varchar(4000),
    "created_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (from_status) REFERENCES order_statuses (code),
    FOREIGN KEY (to_status) REFERENCES order_statuses (code),
    FOREIGN KEY (changed_by_user_id) REFERENCES users (id)
);

CREATE TABLE order_discounts (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "order_id"      bigint NOT NULL,
    "discount_id"   bigint,
    "coupon_id"     bigint,
    "code"          varchar(64),
    "description"   varchar(4000),
    "amount"        decimal(14,4) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (discount_id) REFERENCES discounts (id),
    FOREIGN KEY (coupon_id) REFERENCES coupons (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE fulfillments (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "order_id"     bigint NOT NULL,
    "warehouse_id" bigint,
    "status"       varchar(32) NOT NULL,
    "reference"    varchar(255),
    "packed_at"    timestamp,
    "shipped_at"   timestamp,
    "delivered_at" timestamp,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses (id),
    FOREIGN KEY (status) REFERENCES fulfillment_statuses (code)
);

CREATE TABLE fulfillment_items (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "fulfillment_id" bigint NOT NULL,
    "order_item_id"  bigint NOT NULL,
    "quantity"       integer NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT fulfillment_items_uq UNIQUE (fulfillment_id, order_item_id),
    CHECK (quantity > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (fulfillment_id) REFERENCES fulfillments (id),
    FOREIGN KEY (order_item_id) REFERENCES order_items (id)
);

CREATE TABLE shipments (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "fulfillment_id"  bigint NOT NULL,
    "carrier"         varchar(64) NOT NULL,
    "service_level"   varchar(64),
    "tracking_number" varchar(64),
    "tracking_url"    varchar(2048),
    "shipping_cost"   decimal(14,4),
    "currency_code"   varchar(3),
    "weight_grams"    integer,
    "shipped_at"      timestamp,
    "delivered_at"    timestamp,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (shipping_cost >= 0),
    CHECK (weight_grams >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (fulfillment_id) REFERENCES fulfillments (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE shipment_tracking (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "shipment_id" bigint NOT NULL,
    "status"      varchar(64) NOT NULL,
    "description" varchar(4000),
    "location"    varchar(255),
    "occurred_at" timestamp NOT NULL,
    "created_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (shipment_id) REFERENCES shipments (id)
);

CREATE TABLE order_returns (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "order_id"      bigint NOT NULL,
    "rma_number"    varchar(64) NOT NULL,
    "status"        varchar(32) NOT NULL,
    "reason"        varchar(4000),
    "refund_total"  decimal(14,4) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "requested_at"  timestamp NOT NULL,
    "approved_at"   timestamp,
    "received_at"   timestamp,
    "refunded_at"   timestamp,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT returns_tenant_rma_uq UNIQUE (tenant_id, rma_number),
    CHECK (refund_total >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (status) REFERENCES return_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE return_items (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "return_id"     bigint NOT NULL,
    "order_item_id" bigint NOT NULL,
    "quantity"      integer NOT NULL,
    "reason"        varchar(4000),
    "restock"       boolean NOT NULL,
    "refund_amount" decimal(14,4) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT return_items_uq UNIQUE (return_id, order_item_id),
    CHECK (quantity > 0),
    CHECK (refund_amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (return_id) REFERENCES order_returns (id),
    FOREIGN KEY (order_item_id) REFERENCES order_items (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE gift_cards (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "code"              varchar(64) NOT NULL,
    "status"            varchar(64) NOT NULL,
    "initial_balance"   decimal(14,4) NOT NULL,
    "balance"           decimal(14,4) NOT NULL,
    "currency_code"     varchar(3) NOT NULL,
    "issued_to_user_id" bigint,
    "issued_order_id"   bigint,
    "expires_at"        timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT gift_cards_tenant_code_uq UNIQUE (tenant_id, code),
    CHECK (initial_balance >= 0),
    CHECK (balance >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    FOREIGN KEY (issued_to_user_id) REFERENCES users (id),
    FOREIGN KEY (issued_order_id) REFERENCES orders (id)
);

CREATE TABLE gift_card_transactions (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "gift_card_id"  bigint NOT NULL,
    "order_id"      bigint,
    "amount"        decimal(14,4) NOT NULL,
    "balance_after" decimal(14,4) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "note"          varchar(4000),
    "created_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (balance_after >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (gift_card_id) REFERENCES gift_cards (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE order_notes (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "order_id"       bigint NOT NULL,
    "author_user_id" bigint,
    "body"           varchar(65535) NOT NULL,
    "is_pinned"      boolean NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (author_user_id) REFERENCES users (id)
);

CREATE TABLE draft_orders (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "user_id"            bigint,
    "created_by_user_id" bigint,
    "converted_order_id" bigint,
    "name"               varchar(255),
    "status"             varchar(64) NOT NULL,
    "currency_code"      varchar(3) NOT NULL,
    "subtotal"           decimal(14,4) NOT NULL,
    "grand_total"        decimal(14,4) NOT NULL,
    "payload"            json NOT NULL,
    "expires_at"         timestamp,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (subtotal >= 0),
    CHECK (grand_total >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (created_by_user_id) REFERENCES users (id),
    FOREIGN KEY (converted_order_id) REFERENCES orders (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

-- ==========================================================================
-- billing
-- ==========================================================================

CREATE TABLE payment_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE payment_method_kinds (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE invoice_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE subscription_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE refund_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE ledger_directions (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE billing_intervals (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE billing_profiles (
    "id"                    bigint NOT NULL,
    "tenant_id"             bigint NOT NULL,
    "user_id"               bigint,
    "legal_name"            varchar(255) NOT NULL,
    "billing_email"         varchar(254),
    "tax_id"                varchar(64),
    "net_terms_days"        integer NOT NULL,
    "default_currency_code" varchar(3) NOT NULL,
    "is_default"            boolean NOT NULL,
    "metadata"              json NOT NULL,
    "created_at"            timestamp NOT NULL,
    "updated_at"            timestamp NOT NULL,
    "deleted_at"            timestamp,
    PRIMARY KEY ("id"),
    CHECK (net_terms_days >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (default_currency_code) REFERENCES currencies (code)
);

CREATE TABLE payment_methods (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "user_id"            bigint,
    "billing_profile_id" bigint,
    "kind"               varchar(32) NOT NULL,
    "gateway"            varchar(64) NOT NULL,
    "gateway_token"      varchar(255) NOT NULL,
    "brand"              varchar(255),
    "last4"              varchar(4),
    "exp_month"          smallint,
    "exp_year"           smallint,
    "is_default"         boolean NOT NULL,
    "billing_address_id" bigint,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    "deleted_at"         timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT payment_methods_gateway_token_uq UNIQUE (gateway, gateway_token),
    CHECK (exp_month BETWEEN 1 AND 12),
    CHECK (exp_year >= 2000),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (billing_profile_id) REFERENCES billing_profiles (id),
    FOREIGN KEY (kind) REFERENCES payment_method_kinds (code),
    FOREIGN KEY (billing_address_id) REFERENCES addresses (id)
);

CREATE TABLE payouts (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "currency_code"     varchar(3) NOT NULL,
    "gross_amount"      decimal(14,4) NOT NULL,
    "fee_amount"        decimal(14,4) NOT NULL,
    "net_amount"        decimal(14,4) NOT NULL,
    "status"            varchar(64) NOT NULL,
    "gateway_payout_id" varchar(255),
    "arrival_date"      date,
    "paid_at"           timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (gross_amount >= 0),
    CHECK (fee_amount >= 0),
    CHECK (net_amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE ledger_accounts (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "code"          varchar(64) NOT NULL,
    "name"          varchar(255) NOT NULL,
    "account_type"  varchar(64) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "is_active"     boolean NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT ledger_accounts_tenant_code_uq UNIQUE (tenant_id, code),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE plans (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "code"              varchar(64) NOT NULL,
    "name"              varchar(255) NOT NULL,
    "description"       varchar(4000),
    "default_interval"  varchar(32) NOT NULL,
    "interval_count"    integer NOT NULL,
    "trial_period_days" integer NOT NULL,
    "is_active"         boolean NOT NULL,
    "is_public"         boolean NOT NULL,
    "metadata"          json NOT NULL,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    "deleted_at"        timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT plans_tenant_code_uq UNIQUE (tenant_id, code),
    CHECK (interval_count > 0),
    CHECK (trial_period_days >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (default_interval) REFERENCES billing_intervals (code)
);

CREATE TABLE plan_features (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "plan_id"     bigint NOT NULL,
    "feature_key" varchar(64) NOT NULL,
    "limit_value" bigint,
    "is_enabled"  boolean NOT NULL,
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT plan_features_uq UNIQUE (plan_id, feature_key),
    CHECK (limit_value IS NULL OR limit_value >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (plan_id) REFERENCES plans (id)
);

CREATE TABLE plan_prices (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "plan_id"          bigint NOT NULL,
    "currency_code"    varchar(3) NOT NULL,
    "billing_interval" varchar(32) NOT NULL,
    "interval_count"   integer NOT NULL,
    "amount"           decimal(14,4) NOT NULL,
    "is_active"        boolean NOT NULL,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT plan_prices_uq UNIQUE (plan_id, currency_code, billing_interval, interval_count),
    CHECK (interval_count > 0),
    CHECK (amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (plan_id) REFERENCES plans (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    FOREIGN KEY (billing_interval) REFERENCES billing_intervals (code)
);

CREATE TABLE subscriptions (
    "id"                   bigint NOT NULL,
    "public_id"            uuid NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "user_id"              bigint NOT NULL,
    "plan_id"              bigint NOT NULL,
    "billing_profile_id"   bigint,
    "payment_method_id"    bigint,
    "status"               varchar(32) NOT NULL,
    "currency_code"        varchar(3) NOT NULL,
    "quantity"             integer NOT NULL,
    "trial_ends_at"        timestamp,
    "current_period_start" timestamp,
    "current_period_end"   timestamp,
    "cancel_at_period_end" boolean NOT NULL,
    "canceled_at"          timestamp,
    "started_at"           timestamp NOT NULL,
    "ended_at"             timestamp,
    "metadata"             json NOT NULL,
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT subscriptions_public_id_key UNIQUE (public_id),
    CHECK (quantity > 0),
    CONSTRAINT subscriptions_period_chk CHECK (current_period_end IS NULL OR current_period_start IS NULL OR current_period_end > current_period_start),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (plan_id) REFERENCES plans (id),
    FOREIGN KEY (billing_profile_id) REFERENCES billing_profiles (id),
    FOREIGN KEY (payment_method_id) REFERENCES payment_methods (id),
    FOREIGN KEY (status) REFERENCES subscription_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE invoices (
    "id"                 bigint NOT NULL,
    "public_id"          uuid NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "billing_profile_id" bigint,
    "user_id"            bigint,
    "order_id"           bigint,
    "subscription_id"    bigint,
    "invoice_number"     varchar(64) NOT NULL,
    "status"             varchar(32) NOT NULL,
    "currency_code"      varchar(3) NOT NULL,
    "subtotal"           decimal(14,4) NOT NULL,
    "tax_total"          decimal(14,4) NOT NULL,
    "discount_total"     decimal(14,4) NOT NULL,
    "total"              decimal(14,4) NOT NULL,
    "amount_paid"        decimal(14,4) NOT NULL,
    "amount_due"         decimal(14,4) NOT NULL,
    "issued_at"          timestamp,
    "due_at"             timestamp,
    "paid_at"            timestamp,
    "voided_at"          timestamp,
    "notes"              varchar(4000),
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT invoices_public_id_key UNIQUE (public_id),
    CONSTRAINT invoices_tenant_number_uq UNIQUE (tenant_id, invoice_number),
    CHECK (subtotal >= 0),
    CHECK (tax_total >= 0),
    CHECK (discount_total >= 0),
    CHECK (total >= 0),
    CHECK (amount_paid >= 0),
    CHECK (amount_due >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (billing_profile_id) REFERENCES billing_profiles (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (status) REFERENCES invoice_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    CONSTRAINT invoices_subscription_id_fkey FOREIGN KEY (subscription_id) REFERENCES subscriptions (id)
);

CREATE TABLE payments (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "order_id"          bigint,
    "invoice_id"        bigint,
    "payment_method_id" bigint,
    "status"            varchar(32) NOT NULL,
    "amount"            decimal(14,4) NOT NULL,
    "amount_refunded"   decimal(14,4) NOT NULL,
    "currency_code"     varchar(3) NOT NULL,
    "gateway"           varchar(64) NOT NULL,
    "gateway_charge_id" varchar(255),
    "authorized_at"     timestamp,
    "captured_at"       timestamp,
    "failure_code"      varchar(64),
    "metadata"          json NOT NULL,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (amount >= 0),
    CHECK (amount_refunded >= 0),
    CONSTRAINT payments_refund_le_amount_chk CHECK (amount_refunded <= amount),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (payment_method_id) REFERENCES payment_methods (id),
    FOREIGN KEY (status) REFERENCES payment_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    CONSTRAINT payments_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES invoices (id)
);

CREATE TABLE payment_attempts (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "payment_id"       bigint NOT NULL,
    "attempt_number"   integer NOT NULL,
    "status"           varchar(32) NOT NULL,
    "amount"           decimal(14,4) NOT NULL,
    "currency_code"    varchar(3) NOT NULL,
    "gateway_response" json NOT NULL,
    "error_code"       varchar(64),
    "error_message"    varchar(4000),
    "attempted_at"     timestamp NOT NULL,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT payment_attempts_number_uq UNIQUE (payment_id, attempt_number),
    CHECK (attempt_number > 0),
    CHECK (amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (payment_id) REFERENCES payments (id),
    FOREIGN KEY (status) REFERENCES payment_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE payment_refunds (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "payment_id"        bigint NOT NULL,
    "status"            varchar(32) NOT NULL,
    "amount"            decimal(14,4) NOT NULL,
    "currency_code"     varchar(3) NOT NULL,
    "reason"            varchar(4000),
    "gateway_refund_id" varchar(255),
    "processed_at"      timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (amount > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (payment_id) REFERENCES payments (id),
    FOREIGN KEY (status) REFERENCES refund_statuses (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE credit_notes (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "invoice_id"         bigint,
    "billing_profile_id" bigint,
    "credit_note_number" varchar(64) NOT NULL,
    "currency_code"      varchar(3) NOT NULL,
    "subtotal"           decimal(14,4) NOT NULL,
    "tax_total"          decimal(14,4) NOT NULL,
    "total"              decimal(14,4) NOT NULL,
    "reason"             varchar(4000),
    "issued_at"          timestamp,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT credit_notes_tenant_number_uq UNIQUE (tenant_id, credit_note_number),
    CHECK (subtotal >= 0),
    CHECK (tax_total >= 0),
    CHECK (total >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (invoice_id) REFERENCES invoices (id),
    FOREIGN KEY (billing_profile_id) REFERENCES billing_profiles (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE payout_items (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "payout_id"     bigint NOT NULL,
    "payment_id"    bigint NOT NULL,
    "amount"        decimal(14,4) NOT NULL,
    "fee_amount"    decimal(14,4) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT payout_items_payment_uq UNIQUE (payment_id),
    CHECK (amount >= 0),
    CHECK (fee_amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (payout_id) REFERENCES payouts (id),
    FOREIGN KEY (payment_id) REFERENCES payments (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE ledger_entries (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "ledger_account_id" bigint NOT NULL,
    "entry_group"       uuid NOT NULL,
    "direction"         varchar(32) NOT NULL,
    "amount"            decimal(14,4) NOT NULL,
    "currency_code"     varchar(3) NOT NULL,
    "payment_id"        bigint,
    "invoice_id"        bigint,
    "description"       varchar(4000),
    "occurred_at"       timestamp NOT NULL,
    "created_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (amount > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ledger_account_id) REFERENCES ledger_accounts (id),
    FOREIGN KEY (direction) REFERENCES ledger_directions (code),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    FOREIGN KEY (payment_id) REFERENCES payments (id),
    FOREIGN KEY (invoice_id) REFERENCES invoices (id)
);

CREATE TABLE subscription_items (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "subscription_id" bigint NOT NULL,
    "plan_price_id"   bigint,
    "description"     varchar(4000),
    "quantity"        integer NOT NULL,
    "unit_amount"     decimal(14,4) NOT NULL,
    "currency_code"   varchar(3) NOT NULL,
    "is_metered"      boolean NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity > 0),
    CHECK (unit_amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (subscription_id) REFERENCES subscriptions (id),
    FOREIGN KEY (plan_price_id) REFERENCES plan_prices (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE invoice_lines (
    "id"                   bigint NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "invoice_id"           bigint NOT NULL,
    "subscription_item_id" bigint,
    "description"          varchar(4000) NOT NULL,
    "quantity"             decimal(14,4) NOT NULL,
    "unit_price"           decimal(14,4) NOT NULL,
    "line_total"           decimal(14,4) NOT NULL,
    "tax_amount"           decimal(14,4) NOT NULL,
    "currency_code"        varchar(3) NOT NULL,
    "period_start"         timestamp,
    "period_end"           timestamp,
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity > 0),
    CHECK (unit_price >= 0),
    CHECK (line_total >= 0),
    CHECK (tax_amount >= 0),
    CONSTRAINT invoice_lines_period_chk CHECK (period_end IS NULL OR period_start IS NULL OR period_end > period_start),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (invoice_id) REFERENCES invoices (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    CONSTRAINT invoice_lines_subscription_item_id_fkey FOREIGN KEY (subscription_item_id) REFERENCES subscription_items (id)
);

CREATE TABLE credit_note_lines (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "credit_note_id"  bigint NOT NULL,
    "invoice_line_id" bigint,
    "description"     varchar(4000) NOT NULL,
    "quantity"        decimal(14,4) NOT NULL,
    "unit_price"      decimal(14,4) NOT NULL,
    "line_total"      decimal(14,4) NOT NULL,
    "tax_amount"      decimal(14,4) NOT NULL,
    "currency_code"   varchar(3) NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity > 0),
    CHECK (unit_price >= 0),
    CHECK (line_total >= 0),
    CHECK (tax_amount >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (credit_note_id) REFERENCES credit_notes (id),
    FOREIGN KEY (invoice_line_id) REFERENCES invoice_lines (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE usage_records (
    "id"                   bigint NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "subscription_item_id" bigint NOT NULL,
    "quantity"             decimal(14,4) NOT NULL,
    "unit"                 varchar(64),
    "action"               varchar(64) NOT NULL,
    "occurred_at"          timestamp NOT NULL,
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (subscription_item_id) REFERENCES subscription_items (id)
);

CREATE TABLE dunning_attempts (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "invoice_id"      bigint NOT NULL,
    "subscription_id" bigint,
    "payment_id"      bigint,
    "attempt_number"  integer NOT NULL,
    "outcome"         varchar(64) NOT NULL,
    "next_attempt_at" timestamp,
    "attempted_at"    timestamp NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT dunning_attempts_number_uq UNIQUE (invoice_id, attempt_number),
    CHECK (attempt_number > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (invoice_id) REFERENCES invoices (id),
    FOREIGN KEY (subscription_id) REFERENCES subscriptions (id),
    FOREIGN KEY (payment_id) REFERENCES payments (id)
);

CREATE TABLE tax_registrations (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "billing_profile_id"  bigint,
    "country_code"        varchar(2) NOT NULL,
    "jurisdiction"        varchar(64),
    "tax_type"            varchar(64) NOT NULL,
    "registration_number" varchar(64) NOT NULL,
    "is_active"           boolean NOT NULL,
    "valid_from"          date,
    "valid_until"         date,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT tax_registrations_uq UNIQUE (tenant_id, country_code, tax_type),
    CONSTRAINT tax_registrations_validity_chk CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_until > valid_from),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (billing_profile_id) REFERENCES billing_profiles (id)
);

CREATE TABLE wallets (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "user_id"       bigint NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "balance"       decimal(14,4) NOT NULL,
    "is_active"     boolean NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT wallets_user_currency_uq UNIQUE (user_id, currency_code),
    CHECK (balance >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

-- ==========================================================================
-- crm
-- ==========================================================================

CREATE TABLE lead_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE activity_kinds (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE accounts (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "name"           varchar(255) NOT NULL,
    "legal_name"     varchar(255),
    "domain"         varchar(255),
    "industry"       varchar(255),
    "employee_count" integer,
    "annual_revenue" decimal(14,4),
    "currency_code"  varchar(3),
    "owner_user_id"  bigint,
    "phone"          varchar(32),
    "website"        varchar(2048),
    "is_active"      boolean NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    "deleted_at"     timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT accounts_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (employee_count >= 0),
    CHECK (annual_revenue >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    FOREIGN KEY (owner_user_id) REFERENCES users (id)
);

CREATE TABLE contacts (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "account_id"     bigint,
    "owner_user_id"  bigint,
    "first_name"     varchar(255),
    "last_name"      varchar(255),
    "primary_email"  varchar(254),
    "phone"          varchar(32),
    "job_title"      varchar(255),
    "department"     varchar(255),
    "is_primary"     boolean NOT NULL,
    "do_not_contact" boolean NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    "deleted_at"     timestamp,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (account_id) REFERENCES accounts (id),
    FOREIGN KEY (owner_user_id) REFERENCES users (id)
);

CREATE TABLE contact_emails (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "contact_id"  bigint NOT NULL,
    "email"       varchar(254) NOT NULL,
    "label"       varchar(255) NOT NULL,
    "is_primary"  boolean NOT NULL,
    "verified_at" timestamp,
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT contact_emails_contact_email_uq UNIQUE (contact_id, email),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (contact_id) REFERENCES contacts (id)
);

CREATE TABLE leads (
    "id"                   bigint NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "owner_user_id"        bigint,
    "first_name"           varchar(255),
    "last_name"            varchar(255),
    "email"                varchar(254),
    "phone"                varchar(32),
    "company"              varchar(255),
    "job_title"            varchar(255),
    "status"               varchar(32) NOT NULL,
    "source"               varchar(64),
    "score"                integer NOT NULL,
    "converted_account_id" bigint,
    "converted_contact_id" bigint,
    "converted_at"         timestamp,
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (score >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (owner_user_id) REFERENCES users (id),
    FOREIGN KEY (status) REFERENCES lead_statuses (code),
    FOREIGN KEY (converted_account_id) REFERENCES accounts (id),
    FOREIGN KEY (converted_contact_id) REFERENCES contacts (id)
);

CREATE TABLE pipelines (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "name"        varchar(255) NOT NULL,
    "description" varchar(4000),
    "is_default"  boolean NOT NULL,
    "is_active"   boolean NOT NULL,
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT pipelines_tenant_name_uq UNIQUE (tenant_id, name),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE opportunity_stages (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "pipeline_id"     bigint NOT NULL,
    "name"            varchar(255) NOT NULL,
    "sort_position"   integer NOT NULL,
    "win_probability" decimal(5,4) NOT NULL,
    "is_won"          boolean NOT NULL,
    "is_lost"         boolean NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT opportunity_stages_pipeline_position_uq UNIQUE (pipeline_id, sort_position),
    CONSTRAINT opportunity_stages_pipeline_name_uq UNIQUE (pipeline_id, name),
    CHECK (sort_position >= 0),
    CHECK (win_probability >= 0 AND win_probability <= 1),
    CONSTRAINT opportunity_stages_not_won_and_lost CHECK (NOT (is_won AND is_lost)),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (pipeline_id) REFERENCES pipelines (id)
);

CREATE TABLE opportunities (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "account_id"          bigint NOT NULL,
    "pipeline_id"         bigint NOT NULL,
    "stage_id"            bigint NOT NULL,
    "primary_contact_id"  bigint,
    "owner_user_id"       bigint,
    "name"                varchar(255) NOT NULL,
    "amount"              decimal(14,4) NOT NULL,
    "currency_code"       varchar(3) NOT NULL,
    "probability"         decimal(5,4),
    "source"              varchar(64),
    "is_closed"           boolean NOT NULL,
    "is_won"              boolean NOT NULL,
    "expected_close_date" date,
    "closed_at"           timestamp,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (amount >= 0),
    CHECK (probability >= 0 AND probability <= 1),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (account_id) REFERENCES accounts (id),
    FOREIGN KEY (pipeline_id) REFERENCES pipelines (id),
    FOREIGN KEY (stage_id) REFERENCES opportunity_stages (id),
    FOREIGN KEY (primary_contact_id) REFERENCES contacts (id),
    FOREIGN KEY (owner_user_id) REFERENCES users (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE deals (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "account_id"     bigint NOT NULL,
    "opportunity_id" bigint,
    "owner_user_id"  bigint,
    "name"           varchar(255) NOT NULL,
    "contract_value" decimal(14,4) NOT NULL,
    "currency_code"  varchar(3) NOT NULL,
    "signed_at"      date,
    "starts_at"      date,
    "ends_at"        date,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (contract_value >= 0),
    CONSTRAINT deals_term_valid CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (account_id) REFERENCES accounts (id),
    FOREIGN KEY (opportunity_id) REFERENCES opportunities (id),
    FOREIGN KEY (owner_user_id) REFERENCES users (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE deal_line_items (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "deal_id"       bigint NOT NULL,
    "product_id"    bigint,
    "description"   varchar(4000),
    "quantity"      integer NOT NULL,
    "unit_price"    decimal(14,4) NOT NULL,
    "discount_pct"  decimal(5,4) NOT NULL,
    "currency_code" varchar(3) NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (quantity > 0),
    CHECK (unit_price >= 0),
    CHECK (discount_pct >= 0 AND discount_pct <= 1),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (deal_id) REFERENCES deals (id),
    FOREIGN KEY (product_id) REFERENCES products (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE activities (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "kind"             varchar(32) NOT NULL,
    "account_id"       bigint,
    "contact_id"       bigint,
    "opportunity_id"   bigint,
    "owner_user_id"    bigint,
    "subject"          varchar(255),
    "body"             varchar(65535),
    "occurred_at"      timestamp NOT NULL,
    "duration_minutes" integer,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (duration_minutes >= 0),
    CONSTRAINT activities_has_target CHECK ( account_id IS NOT NULL OR contact_id IS NOT NULL OR opportunity_id IS NOT NULL ),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (kind) REFERENCES activity_kinds (code),
    FOREIGN KEY (account_id) REFERENCES accounts (id),
    FOREIGN KEY (contact_id) REFERENCES contacts (id),
    FOREIGN KEY (opportunity_id) REFERENCES opportunities (id),
    FOREIGN KEY (owner_user_id) REFERENCES users (id)
);

CREATE TABLE crm_notes (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "account_id"     bigint,
    "contact_id"     bigint,
    "opportunity_id" bigint,
    "author_user_id" bigint,
    "body"           varchar(65535) NOT NULL,
    "is_pinned"      boolean NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT crm_notes_has_target CHECK ( account_id IS NOT NULL OR contact_id IS NOT NULL OR opportunity_id IS NOT NULL ),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (account_id) REFERENCES accounts (id),
    FOREIGN KEY (contact_id) REFERENCES contacts (id),
    FOREIGN KEY (opportunity_id) REFERENCES opportunities (id),
    FOREIGN KEY (author_user_id) REFERENCES users (id)
);

CREATE TABLE tasks (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "assignee_user_id" bigint,
    "account_id"       bigint,
    "contact_id"       bigint,
    "opportunity_id"   bigint,
    "title"            varchar(255) NOT NULL,
    "description"      varchar(4000),
    "priority"         varchar(64) NOT NULL,
    "is_done"          boolean NOT NULL,
    "due_at"           timestamp,
    "completed_at"     timestamp,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (assignee_user_id) REFERENCES users (id),
    FOREIGN KEY (account_id) REFERENCES accounts (id),
    FOREIGN KEY (contact_id) REFERENCES contacts (id),
    FOREIGN KEY (opportunity_id) REFERENCES opportunities (id)
);

CREATE TABLE account_relationships (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "parent_account_id" bigint NOT NULL,
    "child_account_id"  bigint NOT NULL,
    "relationship_type" varchar(64) NOT NULL,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT account_relationships_uq UNIQUE (parent_account_id, child_account_id, relationship_type),
    CONSTRAINT account_relationships_no_self CHECK (parent_account_id <> child_account_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (parent_account_id) REFERENCES accounts (id),
    FOREIGN KEY (child_account_id) REFERENCES accounts (id)
);

CREATE TABLE contact_lists (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "owner_user_id" bigint,
    "name"          varchar(255) NOT NULL,
    "description"   varchar(4000),
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT contact_lists_tenant_name_uq UNIQUE (tenant_id, name),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (owner_user_id) REFERENCES users (id)
);

CREATE TABLE contact_list_members (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "contact_list_id"  bigint NOT NULL,
    "contact_id"       bigint NOT NULL,
    "added_by_user_id" bigint,
    "created_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT contact_list_members_uq UNIQUE (contact_list_id, contact_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (contact_list_id) REFERENCES contact_lists (id),
    FOREIGN KEY (contact_id) REFERENCES contacts (id),
    FOREIGN KEY (added_by_user_id) REFERENCES users (id)
);

-- ==========================================================================
-- support
-- ==========================================================================

CREATE TABLE ticket_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE ticket_priorities (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE support_channels (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE support_agents (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "user_id"          bigint NOT NULL,
    "display_name"     varchar(255),
    "signature"        varchar(255),
    "is_available"     boolean NOT NULL,
    "max_open_tickets" integer NOT NULL,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT support_agents_user_uq UNIQUE (tenant_id, user_id),
    CHECK (max_open_tickets >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE agent_groups (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "name"        varchar(255) NOT NULL,
    "description" varchar(4000),
    "is_active"   boolean NOT NULL,
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT agent_groups_tenant_name_uq UNIQUE (tenant_id, name),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE agent_group_members (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "agent_group_id"   bigint NOT NULL,
    "support_agent_id" bigint NOT NULL,
    "is_lead"          boolean NOT NULL,
    "created_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT agent_group_members_uq UNIQUE (agent_group_id, support_agent_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (agent_group_id) REFERENCES agent_groups (id),
    FOREIGN KEY (support_agent_id) REFERENCES support_agents (id)
);

CREATE TABLE sla_policies (
    "id"                            bigint NOT NULL,
    "tenant_id"                     bigint NOT NULL,
    "name"                          varchar(255) NOT NULL,
    "priority"                      varchar(32),
    "first_response_target_minutes" integer NOT NULL,
    "resolution_target_minutes"     integer NOT NULL,
    "business_hours_only"           boolean NOT NULL,
    "is_active"                     boolean NOT NULL,
    "created_at"                    timestamp NOT NULL,
    "updated_at"                    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT sla_policies_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (first_response_target_minutes > 0),
    CHECK (resolution_target_minutes > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (priority) REFERENCES ticket_priorities (code)
);

CREATE TABLE support_tags (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "name"       varchar(255) NOT NULL,
    "color"      varchar(64),
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT support_tags_tenant_name_uq UNIQUE (tenant_id, name),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE knowledge_categories (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "name"               varchar(255) NOT NULL,
    "slug"               varchar(255) NOT NULL,
    "parent_category_id" bigint,
    "sort_position"      integer NOT NULL,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT knowledge_categories_slug_uq UNIQUE (tenant_id, slug),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (parent_category_id) REFERENCES knowledge_categories (id)
);

CREATE TABLE knowledge_articles (
    "id"                    bigint NOT NULL,
    "tenant_id"             bigint NOT NULL,
    "knowledge_category_id" bigint,
    "author_user_id"        bigint,
    "title"                 varchar(255) NOT NULL,
    "slug"                  varchar(255) NOT NULL,
    "body"                  varchar(65535),
    "is_published"          boolean NOT NULL,
    "view_count"            bigint NOT NULL,
    "helpful_count"         integer NOT NULL,
    "not_helpful_count"     integer NOT NULL,
    "published_at"          timestamp,
    "created_at"            timestamp NOT NULL,
    "updated_at"            timestamp NOT NULL,
    "deleted_at"            timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT knowledge_articles_slug_uq UNIQUE (tenant_id, slug),
    CHECK (view_count >= 0),
    CHECK (helpful_count >= 0),
    CHECK (not_helpful_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (knowledge_category_id) REFERENCES knowledge_categories (id),
    FOREIGN KEY (author_user_id) REFERENCES users (id)
);

CREATE TABLE article_feedback (
    "id"                   bigint NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "knowledge_article_id" bigint NOT NULL,
    "user_id"              bigint,
    "was_helpful"          boolean NOT NULL,
    "comment"              varchar(4000),
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (knowledge_article_id) REFERENCES knowledge_articles (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE macros (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "created_by_agent_id" bigint,
    "title"               varchar(255) NOT NULL,
    "body"                varchar(65535) NOT NULL,
    "is_shared"           boolean NOT NULL,
    "usage_count"         bigint NOT NULL,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    "deleted_at"          timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT macros_tenant_title_uq UNIQUE (tenant_id, title),
    CHECK (usage_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (created_by_agent_id) REFERENCES support_agents (id)
);

CREATE TABLE tickets (
    "id"                bigint NOT NULL,
    "public_id"         uuid NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "requester_user_id" bigint NOT NULL,
    "assignee_agent_id" bigint,
    "agent_group_id"    bigint,
    "sla_policy_id"     bigint,
    "subject"           varchar(255) NOT NULL,
    "status"            varchar(32) NOT NULL,
    "priority"          varchar(32) NOT NULL,
    "channel"           varchar(32) NOT NULL,
    "first_response_at" timestamp,
    "resolved_at"       timestamp,
    "closed_at"         timestamp,
    "last_message_at"   timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT tickets_public_id_key UNIQUE (public_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (requester_user_id) REFERENCES users (id),
    FOREIGN KEY (assignee_agent_id) REFERENCES support_agents (id),
    FOREIGN KEY (agent_group_id) REFERENCES agent_groups (id),
    FOREIGN KEY (sla_policy_id) REFERENCES sla_policies (id),
    FOREIGN KEY (status) REFERENCES ticket_statuses (code),
    FOREIGN KEY (priority) REFERENCES ticket_priorities (code),
    FOREIGN KEY (channel) REFERENCES support_channels (code)
);

CREATE TABLE ticket_messages (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "ticket_id"       bigint NOT NULL,
    "author_user_id"  bigint,
    "author_agent_id" bigint,
    "body"            varchar(65535) NOT NULL,
    "is_public"       boolean NOT NULL,
    "channel"         varchar(32),
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ticket_id) REFERENCES tickets (id),
    FOREIGN KEY (author_user_id) REFERENCES users (id),
    FOREIGN KEY (author_agent_id) REFERENCES support_agents (id),
    FOREIGN KEY (channel) REFERENCES support_channels (code)
);

CREATE TABLE ticket_events (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "ticket_id"      bigint NOT NULL,
    "actor_user_id"  bigint,
    "actor_agent_id" bigint,
    "event_type"     varchar(64) NOT NULL,
    "old_value"      varchar(4000),
    "new_value"      varchar(4000),
    "metadata"       json NOT NULL,
    "occurred_at"    timestamp NOT NULL,
    "created_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ticket_id) REFERENCES tickets (id),
    FOREIGN KEY (actor_user_id) REFERENCES users (id),
    FOREIGN KEY (actor_agent_id) REFERENCES support_agents (id)
);

CREATE TABLE ticket_tags_map (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "ticket_id"      bigint NOT NULL,
    "support_tag_id" bigint NOT NULL,
    "created_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT ticket_tags_map_uq UNIQUE (ticket_id, support_tag_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ticket_id) REFERENCES tickets (id),
    FOREIGN KEY (support_tag_id) REFERENCES support_tags (id)
);

CREATE TABLE sla_breaches (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "ticket_id"     bigint NOT NULL,
    "sla_policy_id" bigint,
    "breach_kind"   varchar(64) NOT NULL,
    "target_at"     timestamp NOT NULL,
    "breached_at"   timestamp NOT NULL,
    "minutes_over"  integer,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (minutes_over >= 0),
    CONSTRAINT sla_breaches_after_target_chk CHECK (breached_at >= target_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ticket_id) REFERENCES tickets (id),
    FOREIGN KEY (sla_policy_id) REFERENCES sla_policies (id)
);

CREATE TABLE csat_responses (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "ticket_id"          bigint NOT NULL,
    "respondent_user_id" bigint,
    "rated_agent_id"     bigint,
    "score"              integer NOT NULL,
    "comment"            varchar(4000),
    "submitted_at"       timestamp NOT NULL,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT csat_responses_ticket_uq UNIQUE (ticket_id),
    CHECK (score BETWEEN 1 AND 5),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ticket_id) REFERENCES tickets (id),
    FOREIGN KEY (respondent_user_id) REFERENCES users (id),
    FOREIGN KEY (rated_agent_id) REFERENCES support_agents (id)
);

-- ==========================================================================
-- marketing
-- ==========================================================================

CREATE TABLE campaign_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE send_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE experiment_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE email_templates (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "name"       varchar(255) NOT NULL,
    "subject"    varchar(255) NOT NULL,
    "body_html"  varchar(65535),
    "body_text"  varchar(65535),
    "from_name"  varchar(255),
    "from_email" varchar(254),
    "is_active"  boolean NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    "deleted_at" timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT email_templates_tenant_name_uq UNIQUE (tenant_id, name),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE segments (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "name"              varchar(255) NOT NULL,
    "description"       varchar(4000),
    "rules"             json NOT NULL,
    "is_dynamic"        boolean NOT NULL,
    "member_count"      integer NOT NULL,
    "last_refreshed_at" timestamp,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    "deleted_at"        timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT segments_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (member_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE segment_members (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "segment_id" bigint NOT NULL,
    "user_id"    bigint NOT NULL,
    "added_at"   timestamp NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT segment_members_uq UNIQUE (segment_id, user_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (segment_id) REFERENCES segments (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE landing_pages (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "slug"         varchar(255) NOT NULL,
    "title"        varchar(255) NOT NULL,
    "url"          varchar(2048),
    "content_html" varchar(65535),
    "is_published" boolean NOT NULL,
    "published_at" timestamp,
    "view_count"   bigint NOT NULL,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    "deleted_at"   timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT landing_pages_tenant_slug_uq UNIQUE (tenant_id, slug),
    CHECK (view_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE campaigns (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "name"               varchar(255) NOT NULL,
    "description"        varchar(4000),
    "channel"            varchar(64) NOT NULL,
    "status"             varchar(32) NOT NULL,
    "segment_id"         bigint,
    "email_template_id"  bigint,
    "landing_page_id"    bigint,
    "promotion_id"       bigint,
    "budget"             decimal(14,4),
    "currency_code"      varchar(3),
    "scheduled_at"       timestamp,
    "started_at"         timestamp,
    "ended_at"           timestamp,
    "created_by_user_id" bigint,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    "deleted_at"         timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT campaigns_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (budget >= 0),
    CONSTRAINT campaigns_window_chk CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at > started_at),
    CONSTRAINT campaigns_budget_currency_chk CHECK (budget IS NULL OR currency_code IS NOT NULL),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (status) REFERENCES campaign_statuses (code),
    FOREIGN KEY (segment_id) REFERENCES segments (id),
    FOREIGN KEY (email_template_id) REFERENCES email_templates (id),
    FOREIGN KEY (landing_page_id) REFERENCES landing_pages (id),
    FOREIGN KEY (promotion_id) REFERENCES promotions (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code),
    FOREIGN KEY (created_by_user_id) REFERENCES users (id)
);

CREATE TABLE campaign_messages (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "campaign_id"       bigint NOT NULL,
    "user_id"           bigint NOT NULL,
    "email_template_id" bigint,
    "status"            varchar(32) NOT NULL,
    "recipient_email"   varchar(254),
    "sent_at"           timestamp,
    "delivered_at"      timestamp,
    "opened_at"         timestamp,
    "clicked_at"        timestamp,
    "bounced_at"        timestamp,
    "unsubscribed_at"   timestamp,
    "error_message"     varchar(4000),
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (campaign_id) REFERENCES campaigns (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (email_template_id) REFERENCES email_templates (id),
    FOREIGN KEY (status) REFERENCES send_statuses (code)
);

CREATE TABLE ab_tests (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "campaign_id"       bigint,
    "name"              varchar(255) NOT NULL,
    "hypothesis"        varchar(4000),
    "status"            varchar(32) NOT NULL,
    "goal_metric"       varchar(255),
    "started_at"        timestamp,
    "ended_at"          timestamp,
    "winner_variant_id" bigint,
    "created_at"        timestamp NOT NULL,
    "updated_at"        timestamp NOT NULL,
    "deleted_at"        timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT ab_tests_tenant_name_uq UNIQUE (tenant_id, name),
    CONSTRAINT ab_tests_window_chk CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at > started_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (campaign_id) REFERENCES campaigns (id),
    FOREIGN KEY (status) REFERENCES experiment_statuses (code)
);

CREATE TABLE ab_variants (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "ab_test_id"     bigint NOT NULL,
    "name"           varchar(255) NOT NULL,
    "is_control"     boolean NOT NULL,
    "traffic_weight" decimal(5,4) NOT NULL,
    "config"         json NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT ab_variants_test_name_uq UNIQUE (ab_test_id, name),
    CHECK (traffic_weight >= 0 AND traffic_weight <= 1),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ab_test_id) REFERENCES ab_tests (id)
);

CREATE TABLE ab_assignments (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "ab_test_id"    bigint NOT NULL,
    "ab_variant_id" bigint NOT NULL,
    "user_id"       bigint NOT NULL,
    "assigned_at"   timestamp NOT NULL,
    "converted_at"  timestamp,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT ab_assignments_test_user_uq UNIQUE (ab_test_id, user_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (ab_test_id) REFERENCES ab_tests (id),
    FOREIGN KEY (ab_variant_id) REFERENCES ab_variants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE attributions (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "user_id"            bigint,
    "campaign_id"        bigint,
    "order_id"           bigint,
    "model"              varchar(64) NOT NULL,
    "touch_point"        varchar(64),
    "weight"             decimal(5,4) NOT NULL,
    "attributed_revenue" decimal(14,4),
    "currency_code"      varchar(3),
    "occurred_at"        timestamp NOT NULL,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (weight >= 0 AND weight <= 1),
    CHECK (attributed_revenue >= 0),
    CONSTRAINT attributions_revenue_currency_chk CHECK (attributed_revenue IS NULL OR currency_code IS NOT NULL),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (campaign_id) REFERENCES campaigns (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE referrals (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "referrer_user_id" bigint NOT NULL,
    "code"             varchar(64) NOT NULL,
    "reward_amount"    decimal(14,4),
    "currency_code"    varchar(3),
    "max_redemptions"  integer,
    "redemption_count" integer NOT NULL,
    "is_active"        boolean NOT NULL,
    "expires_at"       timestamp,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    "deleted_at"       timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT referrals_tenant_code_uq UNIQUE (tenant_id, code),
    CHECK (reward_amount >= 0),
    CHECK (max_redemptions > 0),
    CHECK (redemption_count >= 0),
    CONSTRAINT referrals_reward_currency_chk CHECK (reward_amount IS NULL OR currency_code IS NOT NULL),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (referrer_user_id) REFERENCES users (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE referral_redemptions (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "referral_id"      bigint NOT NULL,
    "referred_user_id" bigint NOT NULL,
    "order_id"         bigint,
    "reward_amount"    decimal(14,4),
    "currency_code"    varchar(3),
    "redeemed_at"      timestamp NOT NULL,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT referral_redemptions_uq UNIQUE (referral_id, referred_user_id),
    CHECK (reward_amount >= 0),
    CONSTRAINT referral_redemptions_reward_currency_chk CHECK (reward_amount IS NULL OR currency_code IS NOT NULL),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (referral_id) REFERENCES referrals (id),
    FOREIGN KEY (referred_user_id) REFERENCES users (id),
    FOREIGN KEY (order_id) REFERENCES orders (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE loyalty_programs (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "name"                varchar(255) NOT NULL,
    "description"         varchar(4000),
    "points_per_currency" decimal(14,4) NOT NULL,
    "currency_code"       varchar(3) NOT NULL,
    "is_active"           boolean NOT NULL,
    "starts_at"           timestamp,
    "ends_at"             timestamp,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    "deleted_at"          timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT loyalty_programs_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (points_per_currency >= 0),
    CONSTRAINT loyalty_programs_window_chk CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (currency_code) REFERENCES currencies (code)
);

CREATE TABLE loyalty_accounts (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "loyalty_program_id" bigint NOT NULL,
    "user_id"            bigint NOT NULL,
    "points_balance"     bigint NOT NULL,
    "lifetime_points"    bigint NOT NULL,
    "tier"               varchar(64),
    "enrolled_at"        timestamp NOT NULL,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT loyalty_accounts_program_user_uq UNIQUE (loyalty_program_id, user_id),
    CHECK (points_balance >= 0),
    CHECK (lifetime_points >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (loyalty_program_id) REFERENCES loyalty_programs (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE loyalty_transactions (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "loyalty_account_id" bigint NOT NULL,
    "user_id"            bigint NOT NULL,
    "direction"          varchar(64) NOT NULL,
    "points"             bigint NOT NULL,
    "reason"             varchar(4000),
    "order_id"           bigint,
    "balance_after"      bigint,
    "occurred_at"        timestamp NOT NULL,
    "created_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (direction IN ('earn','burn')),
    CHECK (points > 0),
    CHECK (balance_after >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (loyalty_account_id) REFERENCES loyalty_accounts (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (order_id) REFERENCES orders (id)
);

CREATE TABLE utm_links (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "campaign_id"     bigint,
    "landing_page_id" bigint,
    "slug"            varchar(255) NOT NULL,
    "target_url"      varchar(2048) NOT NULL,
    "utm_source"      varchar(255),
    "utm_medium"      varchar(255),
    "utm_campaign"    varchar(255),
    "utm_term"        varchar(255),
    "utm_content"     varchar(255),
    "click_count"     bigint NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    "deleted_at"      timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT utm_links_tenant_slug_uq UNIQUE (tenant_id, slug),
    CHECK (click_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (campaign_id) REFERENCES campaigns (id),
    FOREIGN KEY (landing_page_id) REFERENCES landing_pages (id)
);

-- ==========================================================================
-- analytics
-- ==========================================================================

CREATE TABLE web_sessions (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "user_id"         bigint,
    "anonymous_id"    uuid,
    "started_at"      timestamp NOT NULL,
    "ended_at"        timestamp,
    "landing_page"    varchar(2048),
    "referrer"        varchar(2048),
    "utm_source"      varchar(255),
    "utm_medium"      varchar(255),
    "utm_campaign"    varchar(255),
    "ip_address"      varchar(45),
    "user_agent"      varchar(2048),
    "is_bounce"       boolean NOT NULL,
    "page_view_count" integer NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (page_view_count >= 0),
    CONSTRAINT web_sessions_ended_after_started_ck CHECK (ended_at IS NULL OR ended_at >= started_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE events (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "user_id"        bigint,
    "web_session_id" bigint,
    "event_name"     varchar(64) NOT NULL,
    "properties"     json NOT NULL,
    "occurred_at"    timestamp NOT NULL,
    "created_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (web_session_id) REFERENCES web_sessions (id)
);

CREATE TABLE page_views (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "web_session_id"   bigint NOT NULL,
    "url"              varchar(2048) NOT NULL,
    "path"             varchar(2048),
    "title"            varchar(255),
    "referrer"         varchar(2048),
    "duration_seconds" integer,
    "viewed_at"        timestamp NOT NULL,
    "created_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (duration_seconds >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (web_session_id) REFERENCES web_sessions (id)
);

CREATE TABLE device_profiles (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "user_id"         bigint,
    "fingerprint"     varchar(255) NOT NULL,
    "device_type"     varchar(64),
    "os"              varchar(64),
    "os_version"      varchar(64),
    "browser"         varchar(64),
    "browser_version" varchar(64),
    "screen_width"    integer,
    "screen_height"   integer,
    "first_seen_at"   timestamp NOT NULL,
    "last_seen_at"    timestamp NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT device_profiles_tenant_fingerprint_uq UNIQUE (tenant_id, fingerprint),
    CHECK (screen_width >= 0),
    CHECK (screen_height >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE feature_usage (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "user_id"      bigint,
    "feature_key"  varchar(64) NOT NULL,
    "usage_count"  integer NOT NULL,
    "usage_day"    date NOT NULL,
    "last_used_at" timestamp,
    "occurred_at"  timestamp NOT NULL,
    "created_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT feature_usage_uq UNIQUE (tenant_id, user_id, feature_key, usage_day),
    CHECK (usage_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE experiments (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "key"            varchar(64) NOT NULL,
    "name"           varchar(255) NOT NULL,
    "description"    varchar(4000),
    "hypothesis"     varchar(4000),
    "status"         varchar(32) NOT NULL,
    "primary_metric" varchar(255),
    "starts_at"      timestamp,
    "ends_at"        timestamp,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    "deleted_at"     timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT experiments_tenant_key_uq UNIQUE (tenant_id, key),
    CONSTRAINT experiments_window_ck CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (status) REFERENCES experiment_statuses (code)
);

CREATE TABLE experiment_variants (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "experiment_id"  bigint NOT NULL,
    "key"            varchar(64) NOT NULL,
    "name"           varchar(255) NOT NULL,
    "is_control"     boolean NOT NULL,
    "allocation_pct" decimal(5,2) NOT NULL,
    "config"         json NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT experiment_variants_key_uq UNIQUE (experiment_id, key),
    CHECK (allocation_pct >= 0 AND allocation_pct <= 100),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (experiment_id) REFERENCES experiments (id)
);

CREATE TABLE experiment_assignments (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "experiment_id" bigint NOT NULL,
    "variant_id"    bigint NOT NULL,
    "user_id"       bigint,
    "anonymous_id"  uuid,
    "assigned_at"   timestamp NOT NULL,
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT experiment_assignments_user_uq UNIQUE (experiment_id, user_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (experiment_id) REFERENCES experiments (id),
    FOREIGN KEY (variant_id) REFERENCES experiment_variants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE funnels (
    "id"          bigint NOT NULL,
    "tenant_id"   bigint NOT NULL,
    "name"        varchar(255) NOT NULL,
    "description" varchar(4000),
    "is_active"   boolean NOT NULL,
    "window_days" integer,
    "created_at"  timestamp NOT NULL,
    "updated_at"  timestamp NOT NULL,
    "deleted_at"  timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT funnels_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (window_days > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE funnel_steps (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "funnel_id"  bigint NOT NULL,
    "step_order" integer NOT NULL,
    "name"       varchar(255) NOT NULL,
    "event_name" varchar(64) NOT NULL,
    "filters"    json NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT funnel_steps_order_uq UNIQUE (funnel_id, step_order),
    CHECK (step_order >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (funnel_id) REFERENCES funnels (id)
);

CREATE TABLE cohorts (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "name"         varchar(255) NOT NULL,
    "description"  varchar(4000),
    "definition"   json NOT NULL,
    "is_dynamic"   boolean NOT NULL,
    "member_count" integer NOT NULL,
    "computed_at"  timestamp,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    "deleted_at"   timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT cohorts_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (member_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE cohort_members (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "cohort_id"  bigint NOT NULL,
    "user_id"    bigint NOT NULL,
    "added_at"   timestamp NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT cohort_members_uq UNIQUE (cohort_id, user_id),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (cohort_id) REFERENCES cohorts (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE metrics_daily (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "metric_key"   varchar(64) NOT NULL,
    "metric_date"  date NOT NULL,
    "metric_value" decimal(20,6) NOT NULL,
    "dimensions"   json NOT NULL,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT metrics_daily_uq UNIQUE (tenant_id, metric_key, metric_date),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE kpi_snapshots (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "kpi_key"        varchar(64) NOT NULL,
    "period_grain"   varchar(64) NOT NULL,
    "period_start"   date NOT NULL,
    "period_end"     date NOT NULL,
    "kpi_value"      decimal(20,6) NOT NULL,
    "previous_value" decimal(20,6),
    "metadata"       json NOT NULL,
    "captured_at"    timestamp NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT kpi_snapshots_uq UNIQUE (tenant_id, kpi_key, period_grain, period_start),
    CONSTRAINT kpi_snapshots_period_ck CHECK (period_end >= period_start),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

-- ==========================================================================
-- comms
-- ==========================================================================

CREATE TABLE notification_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE delivery_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE message_directions (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE notification_templates (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "code"       varchar(64) NOT NULL,
    "name"       varchar(255) NOT NULL,
    "channel"    varchar(64) NOT NULL,
    "subject"    varchar(255),
    "body"       varchar(65535) NOT NULL,
    "locale"     varchar(5),
    "is_active"  boolean NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT notification_templates_tenant_code_uq UNIQUE (tenant_id, code),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE notifications (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "user_id"      bigint NOT NULL,
    "template_id"  bigint,
    "channel"      varchar(64) NOT NULL,
    "status"       varchar(32) NOT NULL,
    "title"        varchar(255) NOT NULL,
    "body"         varchar(65535),
    "data"         json NOT NULL,
    "sent_at"      timestamp,
    "delivered_at" timestamp,
    "read_at"      timestamp,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (template_id) REFERENCES notification_templates (id),
    FOREIGN KEY (status) REFERENCES notification_statuses (code)
);

CREATE TABLE notification_preferences (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "user_id"    bigint NOT NULL,
    "channel"    varchar(64) NOT NULL,
    "category"   varchar(255) NOT NULL,
    "is_enabled" boolean NOT NULL,
    "created_at" timestamp NOT NULL,
    "updated_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT notification_preferences_uq UNIQUE (user_id, channel, category),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE message_threads (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "user_id"         bigint,
    "subject"         varchar(255),
    "channel"         varchar(64) NOT NULL,
    "is_closed"       boolean NOT NULL,
    "last_message_at" timestamp,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE thread_messages (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "thread_id"      bigint NOT NULL,
    "sender_user_id" bigint,
    "direction"      varchar(32) NOT NULL,
    "body"           varchar(65535) NOT NULL,
    "attachments"    json NOT NULL,
    "read_at"        timestamp,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (thread_id) REFERENCES message_threads (id),
    FOREIGN KEY (sender_user_id) REFERENCES users (id),
    FOREIGN KEY (direction) REFERENCES message_directions (code)
);

CREATE TABLE webhooks (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "created_by_user_id" bigint,
    "name"               varchar(255) NOT NULL,
    "target_url"         varchar(2048) NOT NULL,
    "secret_hash"        varchar(255) NOT NULL,
    "event_types"        varchar(64) ARRAY NOT NULL,
    "is_active"          boolean NOT NULL,
    "last_delivered_at"  timestamp,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (created_by_user_id) REFERENCES users (id)
);

CREATE TABLE webhook_deliveries (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "webhook_id"    bigint NOT NULL,
    "event_type"    varchar(64) NOT NULL,
    "status"        varchar(32) NOT NULL,
    "attempt"       integer NOT NULL,
    "response_code" integer,
    "request_body"  json,
    "response_body" varchar(65535),
    "duration_ms"   integer,
    "delivered_at"  timestamp,
    "created_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (attempt > 0),
    CHECK (response_code BETWEEN 100 AND 599),
    CHECK (duration_ms >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (webhook_id) REFERENCES webhooks (id),
    FOREIGN KEY (status) REFERENCES delivery_statuses (code)
);

CREATE TABLE email_log (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "user_id"             bigint,
    "template_id"         bigint,
    "recipient_email"     varchar(254) NOT NULL,
    "from_email"          varchar(254),
    "subject"             varchar(255),
    "provider"            varchar(64),
    "provider_message_id" varchar(255),
    "status"              varchar(32) NOT NULL,
    "error_message"       varchar(4000),
    "sent_at"             timestamp,
    "created_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (template_id) REFERENCES notification_templates (id),
    FOREIGN KEY (status) REFERENCES delivery_statuses (code)
);

CREATE TABLE sms_log (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "user_id"             bigint,
    "template_id"         bigint,
    "recipient_phone"     varchar(32) NOT NULL,
    "from_number"         varchar(32),
    "body"                varchar(65535) NOT NULL,
    "provider"            varchar(64),
    "provider_message_id" varchar(255),
    "status"              varchar(32) NOT NULL,
    "error_message"       varchar(4000),
    "segments"            integer NOT NULL,
    "sent_at"             timestamp,
    "created_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (segments > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (template_id) REFERENCES notification_templates (id),
    FOREIGN KEY (status) REFERENCES delivery_statuses (code)
);

CREATE TABLE push_tokens (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "user_id"      bigint NOT NULL,
    "platform"     varchar(64) NOT NULL,
    "token"        varchar(255) NOT NULL,
    "device_name"  varchar(255),
    "is_active"    boolean NOT NULL,
    "last_used_at" timestamp,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT push_tokens_tenant_token_uq UNIQUE (tenant_id, token),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE unsubscribes (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "user_id"         bigint,
    "channel"         varchar(64) NOT NULL,
    "address"         varchar(255) NOT NULL,
    "category"        varchar(255) NOT NULL,
    "reason"          varchar(4000),
    "unsubscribed_at" timestamp NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT unsubscribes_uq UNIQUE (tenant_id, channel, address, category),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE contact_channels (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "user_id"         bigint NOT NULL,
    "kind"            varchar(64) NOT NULL,
    "channel_address" varchar(255) NOT NULL,
    "is_primary"      boolean NOT NULL,
    "is_verified"     boolean NOT NULL,
    "verified_at"     timestamp,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT contact_channels_user_kind_value_uq UNIQUE (user_id, kind, channel_address),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

-- ==========================================================================
-- audit
-- ==========================================================================

CREATE TABLE consent_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE audit_actions (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE audit_log (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "action"        varchar(32) NOT NULL,
    "actor_user_id" bigint,
    "actor_type"    varchar(64) NOT NULL,
    "entity_schema" varchar(64),
    "entity_table"  varchar(64),
    "entity_id"     bigint,
    "summary"       varchar(4000),
    "metadata"      json NOT NULL,
    "ip_address"    varchar(45),
    "user_agent"    varchar(2048),
    "request_id"    varchar(64),
    "occurred_at"   timestamp NOT NULL,
    "created_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT audit_log_entity_ref_chk CHECK ((entity_schema IS NULL) = (entity_table IS NULL)),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (action) REFERENCES audit_actions (code),
    FOREIGN KEY (actor_user_id) REFERENCES users (id)
);

CREATE TABLE change_history (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "audit_log_id"    bigint,
    "actor_user_id"   bigint,
    "entity_schema"   varchar(64) NOT NULL,
    "entity_table"    varchar(64) NOT NULL,
    "entity_id"       bigint NOT NULL,
    "changed_columns" varchar(255) ARRAY NOT NULL,
    "before_data"     json NOT NULL,
    "after_data"      json NOT NULL,
    "occurred_at"     timestamp NOT NULL,
    "created_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (audit_log_id) REFERENCES audit_log (id),
    FOREIGN KEY (actor_user_id) REFERENCES users (id)
);

CREATE TABLE access_log (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "actor_user_id" bigint,
    "entity_schema" varchar(64) NOT NULL,
    "entity_table"  varchar(64) NOT NULL,
    "entity_id"     bigint,
    "access_kind"   varchar(64) NOT NULL,
    "field_names"   varchar(255) ARRAY NOT NULL,
    "purpose"       varchar(64),
    "ip_address"    varchar(45),
    "user_agent"    varchar(2048),
    "occurred_at"   timestamp NOT NULL,
    "created_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (actor_user_id) REFERENCES users (id)
);

CREATE TABLE data_exports (
    "id"                   bigint NOT NULL,
    "public_id"            uuid NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "requested_by_user_id" bigint,
    "subject_user_id"      bigint,
    "status"               varchar(64) NOT NULL,
    "format"               varchar(64) NOT NULL,
    "file_url"             varchar(2048),
    "row_count"            bigint,
    "requested_at"         timestamp NOT NULL,
    "completed_at"         timestamp,
    "expires_at"           timestamp,
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT data_exports_public_id_key UNIQUE (public_id),
    CHECK (row_count >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (requested_by_user_id) REFERENCES users (id),
    FOREIGN KEY (subject_user_id) REFERENCES users (id)
);

CREATE TABLE consent_records (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "user_id"        bigint NOT NULL,
    "purpose"        varchar(64) NOT NULL,
    "status"         varchar(32) NOT NULL,
    "source"         varchar(64),
    "policy_version" varchar(64),
    "ip_address"     varchar(45),
    "granted_at"     timestamp,
    "withdrawn_at"   timestamp,
    "expires_at"     timestamp,
    "occurred_at"    timestamp NOT NULL,
    "created_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    FOREIGN KEY (status) REFERENCES consent_statuses (code)
);

CREATE TABLE compliance_events (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "event_type"          varchar(64) NOT NULL,
    "severity"            varchar(64) NOT NULL,
    "detected_by_user_id" bigint,
    "entity_schema"       varchar(64),
    "entity_table"        varchar(64),
    "entity_id"           bigint,
    "details"             json NOT NULL,
    "resolved"            boolean NOT NULL,
    "resolved_at"         timestamp,
    "occurred_at"         timestamp NOT NULL,
    "created_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (detected_by_user_id) REFERENCES users (id)
);

CREATE TABLE data_subject_requests (
    "id"                  bigint NOT NULL,
    "public_id"           uuid NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "subject_user_id"     bigint,
    "subject_email"       varchar(254),
    "request_type"        varchar(64) NOT NULL,
    "status"              varchar(64) NOT NULL,
    "assigned_to_user_id" bigint,
    "data_export_id"      bigint,
    "notes"               varchar(4000),
    "received_at"         timestamp NOT NULL,
    "due_at"              timestamp,
    "completed_at"        timestamp,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT dsr_public_id_key UNIQUE (public_id),
    CONSTRAINT dsr_subject_present_chk CHECK (subject_user_id IS NOT NULL OR subject_email IS NOT NULL),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (subject_user_id) REFERENCES users (id),
    FOREIGN KEY (assigned_to_user_id) REFERENCES users (id),
    FOREIGN KEY (data_export_id) REFERENCES data_exports (id)
);

CREATE TABLE retention_policies (
    "id"               bigint NOT NULL,
    "tenant_id"        bigint NOT NULL,
    "name"             varchar(255) NOT NULL,
    "entity_schema"    varchar(64) NOT NULL,
    "entity_table"     varchar(64) NOT NULL,
    "retention_days"   integer NOT NULL,
    "action_on_expiry" varchar(64) NOT NULL,
    "is_active"        boolean NOT NULL,
    "last_run_at"      timestamp,
    "created_at"       timestamp NOT NULL,
    "updated_at"       timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT retention_policies_entity_uq UNIQUE (tenant_id, entity_schema, entity_table),
    CHECK (retention_days > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE legal_holds (
    "id"                  bigint NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "name"                varchar(255) NOT NULL,
    "reason"              varchar(4000),
    "retention_policy_id" bigint,
    "subject_user_id"     bigint,
    "entity_schema"       varchar(64),
    "entity_table"        varchar(64),
    "entity_id"           bigint,
    "placed_by_user_id"   bigint,
    "is_active"           boolean NOT NULL,
    "placed_at"           timestamp NOT NULL,
    "released_at"         timestamp,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT legal_holds_release_chk CHECK (released_at IS NULL OR released_at >= placed_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (retention_policy_id) REFERENCES retention_policies (id),
    FOREIGN KEY (subject_user_id) REFERENCES users (id),
    FOREIGN KEY (placed_by_user_id) REFERENCES users (id)
);

CREATE TABLE audit_log_archive (
    "id"                  bigint NOT NULL,
    "source_audit_log_id" bigint,
    "tenant_id"           bigint NOT NULL,
    "action"              varchar(32) NOT NULL,
    "actor_user_id"       bigint,
    "actor_type"          varchar(64) NOT NULL,
    "entity_schema"       varchar(64),
    "entity_table"        varchar(64),
    "entity_id"           bigint,
    "summary"             varchar(4000),
    "metadata"            json NOT NULL,
    "ip_address"          varchar(45),
    "user_agent"          varchar(2048),
    "request_id"          varchar(64),
    "occurred_at"         timestamp NOT NULL,
    "archived_at"         timestamp NOT NULL,
    "created_at"          timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (action) REFERENCES audit_actions (code)
);

-- ==========================================================================
-- ops
-- ==========================================================================

CREATE TABLE job_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE integration_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE import_statuses (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE flag_kinds (
    "code"       varchar(32) NOT NULL,
    "sort_order" smallint NOT NULL,
    PRIMARY KEY ("code"),
    UNIQUE (sort_order)
);

CREATE TABLE feature_flags (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "key"                varchar(64) NOT NULL,
    "name"               varchar(255) NOT NULL,
    "description"        varchar(4000),
    "kind"               varchar(32) NOT NULL,
    "is_enabled"         boolean NOT NULL,
    "default_value"      json NOT NULL,
    "rollout_percentage" integer,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT feature_flags_tenant_key_uq UNIQUE (tenant_id, key),
    CHECK (rollout_percentage BETWEEN 0 AND 100),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (kind) REFERENCES flag_kinds (code)
);

CREATE TABLE feature_flag_rules (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "feature_flag_id" bigint NOT NULL,
    "sort_position"   integer NOT NULL,
    "conditions"      json NOT NULL,
    "serve_value"     json NOT NULL,
    "is_active"       boolean NOT NULL,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT feature_flag_rules_position_uq UNIQUE (feature_flag_id, sort_position),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (feature_flag_id) REFERENCES feature_flags (id)
);

CREATE TABLE feature_flag_overrides (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "feature_flag_id" bigint NOT NULL,
    "user_id"         bigint,
    "override_value"  json NOT NULL,
    "reason"          varchar(4000),
    "expires_at"      timestamp,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (feature_flag_id) REFERENCES feature_flags (id),
    FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE settings (
    "id"            bigint NOT NULL,
    "tenant_id"     bigint NOT NULL,
    "setting_key"   varchar(64) NOT NULL,
    "setting_value" json NOT NULL,
    "value_type"    varchar(64) NOT NULL,
    "is_secret"     boolean NOT NULL,
    "description"   varchar(4000),
    "created_at"    timestamp NOT NULL,
    "updated_at"    timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT settings_tenant_key_uq UNIQUE (tenant_id, setting_key),
    CONSTRAINT settings_value_type_chk CHECK (value_type IN ('string','number','boolean','json','date')),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE jobs (
    "id"           bigint NOT NULL,
    "tenant_id"    bigint NOT NULL,
    "name"         varchar(255) NOT NULL,
    "queue"        varchar(64) NOT NULL,
    "handler"      varchar(64) NOT NULL,
    "payload"      json NOT NULL,
    "max_attempts" integer NOT NULL,
    "is_enabled"   boolean NOT NULL,
    "created_at"   timestamp NOT NULL,
    "updated_at"   timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT jobs_tenant_name_uq UNIQUE (tenant_id, name),
    CHECK (max_attempts > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE job_runs (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "job_id"         bigint NOT NULL,
    "status"         varchar(32) NOT NULL,
    "attempt"        integer NOT NULL,
    "queued_at"      timestamp NOT NULL,
    "started_at"     timestamp,
    "finished_at"    timestamp,
    "duration_ms"    integer,
    "error_message"  varchar(4000),
    "result_payload" json,
    "created_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (attempt > 0),
    CHECK (duration_ms >= 0),
    CONSTRAINT job_runs_finish_chk CHECK (finished_at IS NULL OR started_at IS NULL OR finished_at >= started_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (job_id) REFERENCES jobs (id),
    FOREIGN KEY (status) REFERENCES job_statuses (code)
);

CREATE TABLE integrations (
    "id"                   bigint NOT NULL,
    "tenant_id"            bigint NOT NULL,
    "provider"             varchar(64) NOT NULL,
    "name"                 varchar(255) NOT NULL,
    "status"               varchar(32) NOT NULL,
    "config"               json NOT NULL,
    "connected_by_user_id" bigint,
    "connected_at"         timestamp,
    "last_synced_at"       timestamp,
    "last_error"           varchar(4000),
    "created_at"           timestamp NOT NULL,
    "updated_at"           timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT integrations_tenant_provider_name_uq UNIQUE (tenant_id, provider, name),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (status) REFERENCES integration_statuses (code),
    FOREIGN KEY (connected_by_user_id) REFERENCES users (id)
);

CREATE TABLE integration_syncs (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "integration_id"    bigint NOT NULL,
    "status"            varchar(32) NOT NULL,
    "direction"         varchar(64) NOT NULL,
    "records_processed" integer NOT NULL,
    "records_failed"    integer NOT NULL,
    "started_at"        timestamp,
    "finished_at"       timestamp,
    "error_message"     varchar(4000),
    "created_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (records_processed >= 0),
    CHECK (records_failed >= 0),
    CONSTRAINT integration_syncs_direction_chk CHECK (direction IN ('inbound','outbound','bidirectional')),
    CONSTRAINT integration_syncs_finish_chk CHECK (finished_at IS NULL OR started_at IS NULL OR finished_at >= started_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (integration_id) REFERENCES integrations (id),
    FOREIGN KEY (status) REFERENCES job_statuses (code)
);

CREATE TABLE files (
    "id"                  bigint NOT NULL,
    "public_id"           uuid NOT NULL,
    "tenant_id"           bigint NOT NULL,
    "filename"            varchar(255) NOT NULL,
    "content_type"        varchar(64) NOT NULL,
    "byte_size"           bigint NOT NULL,
    "storage_bucket"      varchar(255) NOT NULL,
    "storage_key"         varchar(2048) NOT NULL,
    "checksum"            varchar(255),
    "uploaded_by_user_id" bigint,
    "created_at"          timestamp NOT NULL,
    "updated_at"          timestamp NOT NULL,
    "deleted_at"          timestamp,
    PRIMARY KEY ("id"),
    CONSTRAINT files_public_id_key UNIQUE (public_id),
    CONSTRAINT files_storage_key_uq UNIQUE (storage_bucket, storage_key),
    CHECK (byte_size >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (uploaded_by_user_id) REFERENCES users (id)
);

CREATE TABLE file_versions (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "file_id"            bigint NOT NULL,
    "version"            integer NOT NULL,
    "byte_size"          bigint NOT NULL,
    "storage_key"        varchar(2048) NOT NULL,
    "checksum"           varchar(255),
    "is_current"         boolean NOT NULL,
    "created_by_user_id" bigint,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT file_versions_file_version_uq UNIQUE (file_id, version),
    CHECK (version > 0),
    CHECK (byte_size >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (file_id) REFERENCES files (id),
    FOREIGN KEY (created_by_user_id) REFERENCES users (id)
);

CREATE TABLE import_batches (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "entity_type"        varchar(64) NOT NULL,
    "source_filename"    varchar(255),
    "file_id"            bigint,
    "status"             varchar(32) NOT NULL,
    "total_rows"         integer NOT NULL,
    "processed_rows"     integer NOT NULL,
    "succeeded_rows"     integer NOT NULL,
    "failed_rows"        integer NOT NULL,
    "started_by_user_id" bigint,
    "started_at"         timestamp,
    "finished_at"        timestamp,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (total_rows >= 0),
    CHECK (processed_rows >= 0),
    CHECK (succeeded_rows >= 0),
    CHECK (failed_rows >= 0),
    CONSTRAINT import_batches_finish_chk CHECK (finished_at IS NULL OR started_at IS NULL OR finished_at >= started_at),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (file_id) REFERENCES files (id),
    FOREIGN KEY (status) REFERENCES import_statuses (code),
    FOREIGN KEY (started_by_user_id) REFERENCES users (id)
);

CREATE TABLE import_errors (
    "id"                bigint NOT NULL,
    "tenant_id"         bigint NOT NULL,
    "import_batch_id"   bigint NOT NULL,
    "source_row_number" integer NOT NULL,
    "column_name"       varchar(64),
    "error_code"        varchar(64) NOT NULL,
    "error_message"     varchar(4000) NOT NULL,
    "raw_row"           json,
    "occurred_at"       timestamp NOT NULL,
    "created_at"        timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (source_row_number > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (import_batch_id) REFERENCES import_batches (id)
);

CREATE TABLE scheduled_tasks (
    "id"              bigint NOT NULL,
    "tenant_id"       bigint NOT NULL,
    "name"            varchar(255) NOT NULL,
    "cron_expression" varchar(2048) NOT NULL,
    "timezone"        varchar(64) NOT NULL,
    "job_id"          bigint,
    "is_enabled"      boolean NOT NULL,
    "last_run_at"     timestamp,
    "next_run_at"     timestamp,
    "created_at"      timestamp NOT NULL,
    "updated_at"      timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT scheduled_tasks_tenant_name_uq UNIQUE (tenant_id, name),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (job_id) REFERENCES jobs (id)
);

CREATE TABLE system_health_checks (
    "id"         bigint NOT NULL,
    "tenant_id"  bigint NOT NULL,
    "component"  varchar(255) NOT NULL,
    "is_healthy" boolean NOT NULL,
    "latency_ms" integer,
    "details"    json,
    "checked_at" timestamp NOT NULL,
    "created_at" timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (latency_ms >= 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);

CREATE TABLE rate_limits (
    "id"             bigint NOT NULL,
    "tenant_id"      bigint NOT NULL,
    "api_key_id"     bigint,
    "limit_scope"    varchar(64) NOT NULL,
    "max_requests"   integer NOT NULL,
    "window_seconds" integer NOT NULL,
    "is_enabled"     boolean NOT NULL,
    "created_at"     timestamp NOT NULL,
    "updated_at"     timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CHECK (max_requests > 0),
    CHECK (window_seconds > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (api_key_id) REFERENCES api_keys (id)
);

CREATE TABLE secrets_vault (
    "id"                 bigint NOT NULL,
    "tenant_id"          bigint NOT NULL,
    "key"                varchar(64) NOT NULL,
    "provider"           varchar(64) NOT NULL,
    "external_ref"       varchar(255) NOT NULL,
    "version"            integer NOT NULL,
    "last_rotated_at"    timestamp,
    "expires_at"         timestamp,
    "created_by_user_id" bigint,
    "created_at"         timestamp NOT NULL,
    "updated_at"         timestamp NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT secrets_vault_tenant_key_uq UNIQUE (tenant_id, key),
    CHECK (version > 0),
    FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    FOREIGN KEY (created_by_user_id) REFERENCES users (id)
);
